CREATE TABLE IF NOT EXISTS storeAudit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actorId BIGINT UNSIGNED NOT NULL, action VARCHAR(150) NOT NULL, resourceId VARCHAR(100), details JSON, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, INDEX actor_time(actorId,createdAt)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS productProfiles (productId BIGINT UNSIGNED PRIMARY KEY, body JSON NOT NULL, updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS storeSettings (name VARCHAR(80) PRIMARY KEY, body JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS storeQuotes (id VARCHAR(36) PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, tokenHash VARCHAR(64) NOT NULL UNIQUE, snapshot JSON NOT NULL, expiresAt TIMESTAMP NOT NULL, status VARCHAR(20) DEFAULT 'open' NOT NULL, orderId BIGINT UNSIGNED NULL UNIQUE, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS supportCases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, orderId BIGINT UNSIGNED NOT NULL, kind VARCHAR(30) NOT NULL, subject VARCHAR(160) NOT NULL, status VARCHAR(30) DEFAULT 'open' NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, INDEX owner(userId,createdAt)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS supportMessages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, caseId BIGINT UNSIGNED NOT NULL, actorId BIGINT UNSIGNED NOT NULL, message TEXT NOT NULL, attachments JSON, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, INDEX case_time(caseId,createdAt)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS supportFiles (id VARCHAR(36) PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, caseId BIGINT UNSIGNED NULL, extension VARCHAR(8) NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS serviceZones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, postalCode VARCHAR(5) NOT NULL, label VARCHAR(120) NOT NULL, deliveryCents BIGINT UNSIGNED NOT NULL, installationCents BIGINT UNSIGNED NOT NULL, daysAhead INT UNSIGNED NOT NULL, dailyCapacity INT UNSIGNED NOT NULL, active BOOLEAN DEFAULT TRUE NOT NULL, UNIQUE KEY postal(postalCode)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS serviceBookings (id VARCHAR(36) PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, orderId BIGINT UNSIGNED NOT NULL UNIQUE, zoneId BIGINT UNSIGNED NOT NULL, serviceDate DATE NOT NULL, installation BOOLEAN NOT NULL, status VARCHAR(20) DEFAULT 'requested' NOT NULL, snapshot JSON NOT NULL, INDEX capacity(zoneId,serviceDate,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventoryChannels (id VARCHAR(36) PRIMARY KEY, label VARCHAR(100) NOT NULL, secretHash VARCHAR(64) NOT NULL, userId BIGINT UNSIGNED NOT NULL, enabled BOOLEAN DEFAULT TRUE NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventoryEvents (channelId VARCHAR(36) NOT NULL, eventId VARCHAR(100) NOT NULL, inputHash VARCHAR(64) NOT NULL, orderId BIGINT UNSIGNED NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(channelId,eventId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventoryOutbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, productId BIGINT UNSIGNED NOT NULL, stock INT NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, INDEX cursor_time(id,createdAt)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rewardLedger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, eventKey VARCHAR(100) NOT NULL UNIQUE, points INT NOT NULL, reason VARCHAR(160) NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, INDEX balance_user(userId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rewardBenefits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, description VARCHAR(500) NOT NULL, points INT UNSIGNED NOT NULL, active BOOLEAN DEFAULT TRUE NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rewardRedemptions (id VARCHAR(36) PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, benefitId BIGINT UNSIGNED NOT NULL, snapshot JSON NOT NULL, status VARCHAR(20) DEFAULT 'issued' NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS paymentRefunds (id VARCHAR(36) PRIMARY KEY, orderId BIGINT UNSIGNED NOT NULL UNIQUE, actorId BIGINT UNSIGNED NOT NULL, provider VARCHAR(20) NOT NULL, paymentId VARCHAR(255) NOT NULL, providerRefundId VARCHAR(255), amountCents BIGINT UNSIGNED NOT NULL, state VARCHAR(20) DEFAULT 'creating' NOT NULL, reason VARCHAR(500) NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS adminPasskeys (id VARCHAR(255) PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, publicKey BLOB NOT NULL, counter BIGINT UNSIGNED NOT NULL, transports JSON, label VARCHAR(100) NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, INDEX owner(userId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS passkeyChallenges (id VARCHAR(36) PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, purpose VARCHAR(20) NOT NULL, challenge VARCHAR(255) NOT NULL, expiresAt TIMESTAMP NOT NULL) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ambassador_commissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ambassadorId BIGINT UNSIGNED NOT NULL, subAgentId BIGINT UNSIGNED NOT NULL, rate DECIMAL(5,2) NOT NULL DEFAULT 8.00, notes VARCHAR(255), createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_amb_sub (ambassadorId,subAgentId)) ENGINE=InnoDB;
